fn ndMenuCreate(app: *gtk.Application, label: [:0]const u8) *gtk.Widget {
    menu_app = app;
    const m = gio.Menu.new();
    menu_labels.put(events_gpa, @intFromPtr(m), label) catch {};
    return @ptrCast(@alignCast(m));
}

fn ndMenuItemCreate(app: *gtk.Application, props: ?std.json.Value, dupeZ: *const fn ([]const u8) [:0]const u8) *gtk.Widget {
    menu_app = app;
    const item = gio.MenuItem.new(null, null);
    var info = MenuItemInfo{};
    info.label = dupeZ(propStr(props, "label") orelse "");
    if (propStr(props, "iconName")) |ic| info.icon = dupeZ(ic);
    if (propStr(props, "accelerator")) |ac| info.accel = ndAccelToGtk(ac, dupeZ);
    info.role = parseMenuRole(propStr(props, "role") orelse "none");
    info.enabled = propBool(props, "enabled") orelse true;
    menu_item_info.put(events_gpa, @intFromPtr(item), info) catch {};
    return @ptrCast(@alignCast(item));
}

fn cbMenuActionActivate(_: *gobject.Object, _: ?*glib.Variant, data: ?*anyopaque) callconv(.c) void {
    const node_id: u32 = @intCast(@intFromPtr(data));
    if (emit) |f| f(node_id, "selected", .{});
}

fn cbMenuAboutActivate(_: *gobject.Object, _: ?*glib.Variant, _: ?*anyopaque) callconv(.c) void {
    const dialog = adw.AboutDialog.new();
    if (menu_window) |w| {
        const title = gtk.Window.getTitle(w);
        if (title) |t| adw.AboutDialog.setApplicationName(dialog, t);
    }
    adw.Dialog.present(dialog.as(adw.Dialog), if (menu_window) |w| w.as(gtk.Widget) else null);
}

fn ndMenuEnsureAbout() void {
    if (menu_about_added) return;
    const app = menu_app orelse return;
    const sa = gio.SimpleAction.new("nd-about", null);
    _ = gobject.signalConnectData(@ptrCast(@alignCast(sa)), "activate", @ptrCast(&cbMenuAboutActivate), null, null, .{});
    gio.ActionMap.addAction(app.as(gio.ActionMap), sa.as(gio.Action));
    menu_about_added = true;
}

pub fn ndMenuItemConnect(item_w: *gtk.Widget, node_id: u32) void {
    const item: *gio.MenuItem = @ptrCast(@alignCast(item_w));
    const info = menu_item_info.getPtr(@intFromPtr(item)) orelse return;
    info.node_id = node_id;
    menu_node_ids.put(events_gpa, node_id, @intFromPtr(item)) catch {};
    if (info.role != .none and info.role != .settings) return;
    const app = menu_app orelse return;
    const name = std.fmt.allocPrintSentinel(events_gpa, "nd-menu-{d}", .{node_id}, 0) catch return;
    const sa = gio.SimpleAction.new(name, null);
    info.action = sa;
    _ = gobject.signalConnectData(@ptrCast(@alignCast(sa)), "activate", @ptrCast(&cbMenuActionActivate), @ptrFromInt(@as(usize, node_id)), null, .{});
    gio.SimpleAction.setEnabled(sa, @intFromBool(info.enabled));
    gio.ActionMap.addAction(app.as(gio.ActionMap), sa.as(gio.Action));
    if (info.accel) |accel| {
        const detailed = std.fmt.allocPrintSentinel(events_gpa, "app.nd-menu-{d}", .{node_id}, 0) catch return;
        var accels = [_]?[*:0]const u8{ accel.ptr, null };
        gtk.Application.setAccelsForAction(app, detailed, @ptrCast(&accels));
    }
}

fn ndMenuItemSetEnabled(item_w: *gtk.Widget, enabled: bool) void {
    const item: *gio.MenuItem = @ptrCast(@alignCast(item_w));
    const info = menu_item_info.getPtr(@intFromPtr(item)) orelse return;
    info.enabled = enabled;
    if (info.action) |sa| gio.SimpleAction.setEnabled(sa, @intFromBool(enabled));
}

fn ndBuildGMenuItem(info: MenuItemInfo) ?*gio.MenuItem {
    switch (info.role) {
        .separator, .dropped => return null,
        .about => {
            const lbl: [*:0]const u8 = if (info.label.len > 0) info.label.ptr else "About";
            return gio.MenuItem.new(lbl, "app.nd-about");
        },
        .none, .settings => {
            const lbl: [*:0]const u8 = if (info.label.len > 0) info.label.ptr else (if (info.role == .settings) "Preferences" else "");
            const detailed = std.fmt.allocPrintSentinel(events_gpa, "app.nd-menu-{d}", .{info.node_id}, 0) catch return null;
            return gio.MenuItem.new(lbl, detailed);
        },
    }
}

/// Generic GMenuModel builder over an ordered MIXED list of menu-node handles
/// — GMenuItem leaves (separators split sections) and nested GMenu submenus.
/// Shared by the menubar's per-menu bodies AND every MenuButton/SplitButton
/// popover (M15 generalization of the previously menubar-only builder); item
/// activation routes through the same app-scoped "app.nd-menu-<node>" actions
/// wherever the model is mounted, so MenuItem's `selected` event keeps
/// working for all owners.
fn ndBuildModelFromList(items: []const usize) ?*gio.Menu {
    const root = gio.Menu.new();
    var section = gio.Menu.new();
    var any = false;
    for (items) |item_ptr| {
        if (menu_item_info.get(item_ptr)) |info| {
            if (info.role == .separator) {
                gio.Menu.appendSection(root, null, section.as(gio.MenuModel));
                section = gio.Menu.new();
                continue;
            }
            if (ndBuildGMenuItem(info)) |gi| {
                gio.Menu.appendItem(section, gi);
                any = true;
            }
        } else if (menu_labels.contains(item_ptr) or submenu_items.contains(item_ptr)) {
            // A <menu> child: nested submenu (menubar menus were previously
            // item-only; buttons commonly mix items and submenus).
            const submenu: *gio.Menu = @ptrFromInt(item_ptr);
            if (ndBuildSubmenuModel(submenu)) |model| {
                const label = menu_labels.get(item_ptr) orelse "";
                const lbl: [*:0]const u8 = if (label.len > 0) label.ptr else "Menu";
                gio.Menu.appendSubmenu(section, lbl, model.as(gio.MenuModel));
                any = true;
            }
        }
    }
    gio.Menu.appendSection(root, null, section.as(gio.MenuModel));
    return if (any) root else null;
}

fn ndBuildSubmenuModel(submenu: *gio.Menu) ?*gio.Menu {
    const items = submenu_items.get(@intFromPtr(submenu)) orelse return null;
    return ndBuildModelFromList(items.items);
}

// ---- M15 menu owners: MenuButton/SplitButton host a GMenuModel built from
// their Menu/MenuItem children — the same node handles the menubar tracks,
// rebuilt per owner on every structural change. Keyed by the owner WIDGET. ----
var menu_owner_children: std.AutoHashMapUnmanaged(usize, std.ArrayList(usize)) = .empty;

fn ndMenuOwnerRebuild(owner: *gtk.Widget) void {
    const children = menu_owner_children.get(@intFromPtr(owner)) orelse return;
    const model = ndBuildModelFromList(children.items);
    const mm: ?*gio.MenuModel = if (model) |m| m.as(gio.MenuModel) else null;
    if (gobject.ext.isA(owner, adw.SplitButton)) {
        adw.SplitButton.setMenuModel(@ptrCast(@alignCast(owner)), mm);
    } else if (gobject.ext.isA(owner, gtk.MenuButton)) {
        gtk.MenuButton.setMenuModel(@ptrCast(@alignCast(owner)), mm);
    }
}

fn ndMenuOwnerAppend(owner: *gtk.Widget, child: *gtk.Widget) void {
    const gop = menu_owner_children.getOrPut(events_gpa, @intFromPtr(owner)) catch return;
    if (!gop.found_existing) gop.value_ptr.* = .empty;
    gop.value_ptr.append(events_gpa, @intFromPtr(child)) catch {};
    ndMenuOwnerRebuild(owner);
}

fn ndMenuOwnerRemove(owner: *gtk.Widget, child: *gtk.Widget) void {
    const list = menu_owner_children.getPtr(@intFromPtr(owner)) orelse return;
    for (list.items, 0..) |c, i| {
        if (c == @intFromPtr(child)) {
            _ = list.orderedRemove(i);
            break;
        }
    }
    ndMenuOwnerRebuild(owner);
}

/// Rebuild every registered button owner — called when a Menu's item list
/// mutates AFTER the Menu was appended to its owner (the owner's set model
/// was built from the old list; GMenu handles aren't live-observed here).
fn ndMenuOwnersRefresh() void {
    var it = menu_owner_children.iterator();
    while (it.next()) |e| ndMenuOwnerRebuild(@ptrFromInt(e.key_ptr.*));
}

/// Destroy handler for MenuButton/SplitButton owners: drop the child list so
/// a GLib address reuse can't resurrect a stale menu (mirrors
/// cbHeaderBarDestroyed's eviction rationale).
fn cbMenuOwnerDestroyed(w: *gtk.Widget, _: ?*anyopaque) callconv(.c) void {
    if (menu_owner_children.fetchRemove(@intFromPtr(w))) |kv| {
        var list = kv.value;
        list.deinit(events_gpa);
    }
}

fn ndBuildMenubarModel() ?*gio.Menu {
    const menubar = the_menubar orelse return null;
    const menus = menubar_menus.get(@intFromPtr(menubar)) orelse return null;
    const root = gio.Menu.new();
    var any = false;
    for (menus.items) |submenu_ptr| {
        const submenu: *gio.Menu = @ptrFromInt(submenu_ptr);
        if (ndBuildSubmenuModel(submenu)) |model| {
            const label = menu_labels.get(submenu_ptr) orelse "";
            const lbl: [*:0]const u8 = if (label.len > 0) label.ptr else "Menu";
            gio.Menu.appendSubmenu(root, lbl, model.as(gio.MenuModel));
            any = true;
        }
    }
    return if (any) root else null;
}

fn ndMenuFindSplit(widget: *gtk.Widget, out: *?*adw.OverlaySplitView) void {
    if (out.* != null) return;
    if (gobject.ext.isA(widget, adw.OverlaySplitView)) {
        out.* = @ptrCast(@alignCast(widget));
        return;
    }
    var child = gtk.Widget.getFirstChild(widget);
    while (child) |c| : (child = gtk.Widget.getNextSibling(c)) {
        ndMenuFindSplit(c, out);
        if (out.* != null) return;
    }
}

fn ndMenuFirstHeaderBar(widget: *gtk.Widget, out: *?*adw.HeaderBar) void {
    if (out.* != null) return;
    if (gobject.ext.isA(widget, adw.HeaderBar)) {
        out.* = @ptrCast(@alignCast(widget));
        return;
    }
    var child = gtk.Widget.getFirstChild(widget);
    while (child) |c| : (child = gtk.Widget.getNextSibling(c)) {
        ndMenuFirstHeaderBar(c, out);
        if (out.* != null) return;
    }
}

/// The AdwHeaderBar of the split layout's innermost CONTENT pane — the header the
/// app declares last, where GNOME homes the primary menu button. Found
/// structurally (drill `getContent` through the nested-split pair), so it is
/// stable no matter what order headerbars were created/remounted in — a re-keyed
/// list/sidebar header re-registering last can no longer hijack the button.
/// Returns null (caller falls back to the last-registered header) when the
/// window is not a split layout.
///
/// The window root is taken from the first ALREADY-ROOTED recorded header, not
/// from the header that triggered this refresh: a remount calls here from the
/// new header's create arm, before it is parented, so its `getRoot` is null —
/// anchoring on it would bail to the fallback and let the remounted header steal
/// the button (the exact folder-switch jump this avoids).
fn ndMenuContentHeaderBar() ?*adw.HeaderBar {
    var root: *gtk.Widget = undefined;
    var found_root = false;
    for (menu_headerbars.items) |hb| {
        if (gtk.Widget.getRoot(hb.as(gtk.Widget))) |r| {
            root = @ptrCast(@alignCast(r));
            found_root = true;
            break;
        }
    }
    if (!found_root) return null;
    var split_opt: ?*adw.OverlaySplitView = null;
    ndMenuFindSplit(@ptrCast(@alignCast(root)), &split_opt);
    var split = split_opt orelse return null;
    var content = adw.OverlaySplitView.getContent(split) orelse return null;
    while (gobject.ext.isA(content, adw.OverlaySplitView)) {
        split = @ptrCast(@alignCast(content));
        content = adw.OverlaySplitView.getContent(split) orelse return null;
    }
    var hb_opt: ?*adw.HeaderBar = null;
    ndMenuFirstHeaderBar(content, &hb_opt);
    return hb_opt;
}

fn ndMenuRefresh() void {
    const app = menu_app orelse return;
    if (the_menubar == null) return;
    ndMenuEnsureAbout();
    const model = ndBuildMenubarModel() orelse return;
    if (menu_headerbars.items.len > 0) {
        const any_hb = menu_headerbars.items[menu_headerbars.items.len - 1];
        const target = ndMenuContentHeaderBar() orelse any_hb;
        if (menu_primary_button == null) {
            const btn = gtk.MenuButton.new();
            // Own a strong ref (sinks the floating ref): rehoming does
            // HeaderBar.remove -> packEnd, and remove() would otherwise drop
            // the last ref and destroy the button mid-rehome (observed as
            // GTK_IS_WIDGET / GTK_IS_MENU_BUTTON criticals with 2+ headerbars).
            _ = gobject.Object.refSink(btn.as(gobject.Object));
            gtk.MenuButton.setIconName(btn, "open-menu-symbolic");
            gtk.Widget.setTooltipText(btn.as(gtk.Widget), "Main Menu");
            menu_primary_button = btn;
        }
        const btn = menu_primary_button.?;
        gtk.MenuButton.setMenuModel(btn, model.as(gio.MenuModel));
        if (menu_primary_parent != target) {
            if (menu_primary_parent) |old| adw.HeaderBar.remove(old, btn.as(gtk.Widget));
            adw.HeaderBar.packEnd(target, btn.as(gtk.Widget));
            menu_primary_parent = target;
        }
    } else {
        gtk.Application.setMenubar(app, model.as(gio.MenuModel));
    }
}

fn ndMenubarAppendMenu(menubar_w: *gtk.Widget, menu_w: *gtk.Widget) void {
    const menubar: *gio.Menu = @ptrCast(@alignCast(menubar_w));
    const gop = menubar_menus.getOrPut(events_gpa, @intFromPtr(menubar)) catch return;
    if (!gop.found_existing) gop.value_ptr.* = .empty;
    gop.value_ptr.append(events_gpa, @intFromPtr(menu_w)) catch {};
    ndMenuRefresh();
}

fn ndMenuAppendItem(menu_w: *gtk.Widget, item_w: *gtk.Widget) void {
    const submenu: *gio.Menu = @ptrCast(@alignCast(menu_w));
    const gop = submenu_items.getOrPut(events_gpa, @intFromPtr(submenu)) catch return;
    if (!gop.found_existing) gop.value_ptr.* = .empty;
    gop.value_ptr.append(events_gpa, @intFromPtr(item_w)) catch {};
    ndMenuRefresh();
    ndMenuOwnersRefresh(); // a button owner holding this Menu re-snapshots it
}

/// GObject weak-ref notify: a recorded headerbar is being finalized (the
/// retained tree holds no ref of its own — structural remove drops the
/// container's only ref, src/tree.zig). Purge every unowned pointer to it
/// BEFORE anything dereferences it: menu_primary_parent outliving its
/// headerbar was a real use-after-free (GPF inside adw_header_bar_remove
/// whenever a keyed <headerbar> remounts, e.g. notes' per-folder list header).
fn ndMenuHeaderBarGone(_: ?*anyopaque, where_the_object_was: *gobject.Object) callconv(.c) void {
    const dead: *adw.HeaderBar = @ptrCast(@alignCast(where_the_object_was)); // identity only — never dereferenced
    var i: usize = 0;
    while (i < menu_headerbars.items.len) {
        if (menu_headerbars.items[i] == dead) {
            _ = menu_headerbars.orderedRemove(i);
        } else i += 1;
    }
    if (menu_primary_parent == dead) {
        // The dying container already unparented the button (widget dispose
        // runs before weak notifies fire); the strong ref taken in
        // ndMenuRefresh keeps the button itself alive for re-homing.
        menu_primary_parent = null;
        if (the_menubar != null) ndMenuRefresh();
    }
}

/// Records a headerbar so a later menubar can home its primary button in the
/// LAST one (GNOME convention: the content pane's header). No-op for menu-less
/// apps beyond the record — the button is only created/moved once a <menubar>
/// exists, so counter/gallery/two-pane trees are behaviorally unchanged.
pub fn ndMenuNoteHeaderBar(hb: *adw.HeaderBar) void {
    menu_headerbars.append(events_gpa, hb) catch {};
    gobject.Object.weakRef(hb.as(gobject.Object), &ndMenuHeaderBarGone, null);
    if (the_menubar != null) ndMenuRefresh();
}

/// Called from the Window structural arm when a non-widget child (the menubar
/// GMenu) is appended: install the primary menu instead of setting it as the
/// window content.
pub fn ndMenuAttachToWindow(_: *gtk.Widget) void {
    ndMenuRefresh();
}

// ---- <headerbar> back/forward navigation (canGoBack/canGoForward +
// onBack/onForward). The GNOME idiom is two flat GtkButtons packed at the
// AdwHeaderBar START (go-previous-symbolic / go-next-symbolic). Buttons
// materialize when either prop is PRESENT (the app opts in) — a header with no
// nav props gets none. `node_id` (for emitting back/forward) arrives via
// ndHeaderBarConnectNav, decoupled from button creation, so any create/connect
// order works: the click callbacks look the id up by AdwHeaderBar pointer. ----
const HeaderBarNav = struct { back: *gtk.Button, forward: *gtk.Button };
var headerbar_navs: std.AutoHashMapUnmanaged(usize, HeaderBarNav) = .empty; // AdwHeaderBar ptr -> buttons
var headerbar_nav_ids: std.AutoHashMapUnmanaged(usize, u32) = .empty; // AdwHeaderBar ptr -> node id

fn cbHeaderBarBack(_: *gtk.Button, data: ?*anyopaque) callconv(.c) void {
    const id = headerbar_nav_ids.get(@intFromPtr(data)) orelse return;
    if (emit) |f| f(id, "back", .{});
}

fn cbHeaderBarForward(_: *gtk.Button, data: ?*anyopaque) callconv(.c) void {
    const id = headerbar_nav_ids.get(@intFromPtr(data)) orelse return;
    if (emit) |f| f(id, "forward", .{});
}

/// Evict a header's nav entries when it is finalized. A `key`-based remount
/// (the settings example re-keys the content header per page) destroys the old
/// AdwHeaderBar and GLib readily reuses its address for the new one; without
/// this the stale entry's dangling button pointers would reach setSensitive.
fn cbHeaderBarDestroyed(w: *gtk.Widget, _: ?*anyopaque) callconv(.c) void {
    const key = @intFromPtr(w);
    _ = headerbar_navs.remove(key);
    _ = headerbar_nav_ids.remove(key);
}

/// Materializes / updates the header's flat back/forward buttons from the
/// canGoBack/canGoForward props (generated HeaderBar create + applyProps arms).
/// The buttons appear on the first call carrying either flag and persist; each
/// flag only drives its own button's `sensitive`, so a one-sided diffed update
/// can't clobber the other (mirrors the AppKit segmented-control behaviour).
pub fn ndHeaderBarApplyNav(hb: *adw.HeaderBar, can_back: ?bool, can_forward: ?bool) void {
    if (can_back == null and can_forward == null) return; // untouched: not a teardown
    const gop = headerbar_navs.getOrPut(events_gpa, @intFromPtr(hb)) catch return;
    if (!gop.found_existing) {
        const back = gtk.Button.new();
        gtk.Button.setIconName(back, "go-previous-symbolic");
        gtk.Widget.addCssClass(back.as(gtk.Widget), "flat");
        const forward = gtk.Button.new();
        gtk.Button.setIconName(forward, "go-next-symbolic");
        gtk.Widget.addCssClass(forward.as(gtk.Widget), "flat");
        _ = gtk.Button.signals.clicked.connect(back, ?*anyopaque, &cbHeaderBarBack, @ptrCast(hb), .{});
        _ = gtk.Button.signals.clicked.connect(forward, ?*anyopaque, &cbHeaderBarForward, @ptrCast(hb), .{});
        adw.HeaderBar.packStart(hb, back.as(gtk.Widget)); // back leftmost, forward to its right
        adw.HeaderBar.packStart(hb, forward.as(gtk.Widget));
        _ = gtk.Widget.signals.destroy.connect(hb.as(gtk.Widget), ?*anyopaque, &cbHeaderBarDestroyed, null, .{});
        gop.value_ptr.* = .{ .back = back, .forward = forward };
    }
    if (can_back) |b| gtk.Widget.setSensitive(gop.value_ptr.back.as(gtk.Widget), @intFromBool(b));
    if (can_forward) |f| gtk.Widget.setSensitive(gop.value_ptr.forward.as(gtk.Widget), @intFromBool(f));
}

/// Records the header's node id so the back/forward click callbacks can emit
/// (generated connectEvents HeaderBar arm). The buttons' click handlers are
/// wired in ndHeaderBarApplyNav; this only supplies the id they look up.
pub fn ndHeaderBarConnectNav(widget: *gtk.Widget, node_id: u32) void {
    headerbar_nav_ids.put(events_gpa, @intFromPtr(widget), node_id) catch {};
}

/// backend.zig routes a non-widget node handle's semantic click here.
pub fn menuSemanticClick(node_id: u32) bool {
    const item_ptr = menu_node_ids.get(node_id) orelse return false;
    const info = menu_item_info.get(item_ptr) orelse return true;
    switch (info.role) {
        .about => {
            cbMenuAboutActivate(@ptrCast(menu_app orelse return true), null, null);
            return true;
        },
        .separator, .dropped => return true,
        .none, .settings => {
            const app = menu_app orelse return true;
            if (!info.enabled) return true; // disabled: onSelect must not fire
            const name = std.fmt.allocPrintSentinel(events_gpa, "nd-menu-{d}", .{node_id}, 0) catch return true;
            gio.ActionGroup.activateAction(app.as(gio.ActionGroup), name, null);
            return true;
        },
    }
}

const ND_POPOVER_PENDING_OPEN = "nd-popover-pending-open";

/// Cross-cutting structural rule: a GtkPopover child attaches to its tree
/// parent via gtk_widget_set_parent (never box-packed/slotted — GtkPopover is
/// not a layout child). Called from the appendChild/insertBefore guards;
/// honors a create-time open=true that had to wait for a parent to anchor on.
fn ndPopoverAttach(child: *gtk.Widget, parent: *gtk.Widget) void {
    if (!gobject.ext.isA(parent, gtk.Widget)) return; // menu-node parent: nowhere to anchor
    if (gtk.Widget.getParent(child)) |cur| {
        if (cur == parent) return;
        gtk.Widget.unparent(child);
    }
    gtk.Widget.setParent(child, parent);
    if (gobject.Object.getData(asObject(child), ND_POPOVER_PENDING_OPEN) != null) {
        gobject.Object.setData(asObject(child), ND_POPOVER_PENDING_OPEN, null);
        gtk.Popover.popup(@ptrCast(@alignCast(child)));
    }
}

fn ndPositionFromString(s: []const u8) gtk.PositionType {
    if (std.mem.eql(u8, s, "bottom")) return .bottom;
    if (std.mem.eql(u8, s, "left")) return .left;
    if (std.mem.eql(u8, s, "right")) return .right;
    return .top;
}

// ---- LevelIndicator (GtkLevelBar) tier offsets ----
const NdLevelOffsets = struct { warning: ?f64 = null, critical: ?f64 = null };
var level_offsets: std.AutoHashMapUnmanaged(usize, NdLevelOffsets) = .empty;
var level_css_installed = false;

/// Adwaita styles only the stock low/high/full offsets; ND's warning/critical
/// tiers use custom offset names, colored once app-wide from the platform
/// palette (libadwaita's --warning-bg-color / --error-bg-color variables).
fn ndLevelBarEnsureCss(bar: *gtk.LevelBar) void {
    if (level_css_installed) return;
    level_css_installed = true;
    const provider = gtk.CssProvider.new();
    gtk.CssProvider.loadFromString(provider, "levelbar block.warning { background-color: var(--warning-bg-color); } levelbar block.error { background-color: var(--error-bg-color); }");
    gtk.StyleContext.addProviderForDisplay(gtk.Widget.getDisplay(bar.as(gtk.Widget)), provider.as(gtk.StyleProvider), 600); // STYLE_PROVIDER_PRIORITY_APPLICATION
}

fn cbLevelBarDestroyed(w: *gtk.Widget, _: ?*anyopaque) callconv(.c) void {
    _ = level_offsets.remove(@intFromPtr(w));
}

/// Rising-is-worse tiers (NSLevelIndicator capacity semantics): value at or
/// below warningValue keeps the plain accent fill; above it .warning; above
/// criticalValue .error. GtkLevelBar offsets bracket DOWNWARD (an offset
/// styles the interval it tops), so the tiers translate to: nd-ok topped at
/// warning, warning topped at critical, error topped at max. A null param
/// leaves that threshold as previously applied (diffed prop updates carry
/// only the changed key — same merge ndHeaderBarApplyNav does).
fn ndLevelBarApplyOffsets(bar: *gtk.LevelBar, warning: ?f64, critical: ?f64) void {
    if (warning == null and critical == null) return;
    const gop = level_offsets.getOrPut(events_gpa, @intFromPtr(bar)) catch return;
    if (!gop.found_existing) {
        gop.value_ptr.* = .{};
        _ = gtk.Widget.signals.destroy.connect(bar.as(gtk.Widget), ?*anyopaque, &cbLevelBarDestroyed, null, .{});
    }
    if (warning) |w| gop.value_ptr.warning = w;
    if (critical) |c| gop.value_ptr.critical = c;
    ndLevelBarEnsureCss(bar);
    // Drop the stock offsets so their bracket classes can't fight ND's tiers,
    // then re-add ND's from the merged state (add-with-same-name replaces).
    gtk.LevelBar.removeOffsetValue(bar, "low");
    gtk.LevelBar.removeOffsetValue(bar, "high");
    gtk.LevelBar.removeOffsetValue(bar, "full");
    gtk.LevelBar.removeOffsetValue(bar, "nd-ok");
    gtk.LevelBar.removeOffsetValue(bar, "warning");
    gtk.LevelBar.removeOffsetValue(bar, "error");
    const max = gtk.LevelBar.getMaxValue(bar);
    if (gop.value_ptr.warning) |w| {
        gtk.LevelBar.addOffsetValue(bar, "nd-ok", w);
        gtk.LevelBar.addOffsetValue(bar, "warning", gop.value_ptr.critical orelse max);
        if (gop.value_ptr.critical != null) gtk.LevelBar.addOffsetValue(bar, "error", max);
    } else if (gop.value_ptr.critical) |c| {
        gtk.LevelBar.addOffsetValue(bar, "nd-ok", c);
        gtk.LevelBar.addOffsetValue(bar, "error", max);
    }
}

// ---- ColorPicker (GtkColorDialogButton) hex round-trip ----

/// #rrggbb / #rrggbbaa formatter for the wire value (style.zig's color
/// convention). The alpha byte is included only when not fully opaque.
fn ndRgbaToHex(rgba: *const gdk.RGBA, buf: []u8) []const u8 {
    const r: u32 = @intFromFloat(@round(std.math.clamp(@as(f64, rgba.f_red), 0, 1) * 255.0));
    const g: u32 = @intFromFloat(@round(std.math.clamp(@as(f64, rgba.f_green), 0, 1) * 255.0));
    const b: u32 = @intFromFloat(@round(std.math.clamp(@as(f64, rgba.f_blue), 0, 1) * 255.0));
    const a: u32 = @intFromFloat(@round(std.math.clamp(@as(f64, rgba.f_alpha), 0, 1) * 255.0));
    if (a == 255) return std.fmt.bufPrint(buf, "#{x:0>2}{x:0>2}{x:0>2}", .{ r, g, b }) catch "#000000";
    return std.fmt.bufPrint(buf, "#{x:0>2}{x:0>2}{x:0>2}{x:0>2}", .{ r, g, b, a }) catch "#000000";
}

fn ndRgbaClose(a: *const gdk.RGBA, b: *const gdk.RGBA) bool {
    const eps: f32 = 1.0 / 255.0;
    return @abs(a.f_red - b.f_red) < eps and @abs(a.f_green - b.f_green) < eps and @abs(a.f_blue - b.f_blue) < eps and @abs(a.f_alpha - b.f_alpha) < eps;
}

// ---- DatePicker (GtkCalendar) ISO round-trip + min/max clamp state ----
const NdDateLimits = struct { min: ?i64 = null, max: ?i64 = null };
var calendar_limits: std.AutoHashMapUnmanaged(usize, NdDateLimits) = .empty;

fn cbCalendarDestroyed(w: *gtk.Widget, _: ?*anyopaque) callconv(.c) void {
    _ = calendar_limits.remove(@intFromPtr(w));
}

/// ISO YYYY-MM-DD -> comparable key y*10000 + m*100 + d, or null if malformed.
fn ndDateKeyFromIso(s: []const u8) ?i64 {
    if (s.len != 10 or s[4] != '-' or s[7] != '-') return null;
    const y = std.fmt.parseInt(i64, s[0..4], 10) catch return null;
    const m = std.fmt.parseInt(i64, s[5..7], 10) catch return null;
    const d = std.fmt.parseInt(i64, s[8..10], 10) catch return null;
    if (m < 1 or m > 12 or d < 1 or d > 31) return null;
    return y * 10000 + m * 100 + d;
}

fn ndCalendarDateKey(cal: *gtk.Calendar) i64 {
    const dt = gtk.Calendar.getDate(cal); // transfer full
    defer glib.DateTime.unref(dt);
    const y: i64 = @intCast(glib.DateTime.getYear(dt));
    const m: i64 = @intCast(glib.DateTime.getMonth(dt));
    const d: i64 = @intCast(glib.DateTime.getDayOfMonth(dt));
    return y * 10000 + m * 100 + d;
}

/// GTK 4.20+ deprecated the int day/month/year props; select_day with a
/// GDateTime is the supported `date` surface (design brief 2026-07).
fn ndCalendarSelectKey(cal: *gtk.Calendar, key: i64) void {
    const dt = glib.DateTime.newLocal(@intCast(@divTrunc(key, 10000)), @intCast(@mod(@divTrunc(key, 100), 100)), @intCast(@mod(key, 100)), 0, 0, 0) orelse return;
    defer glib.DateTime.unref(dt);
    gtk.Calendar.selectDay(cal, dt);
}

fn ndIsoFromKey(key: i64, buf: []u8) []const u8 {
    const y: u64 = @intCast(@divTrunc(key, 10000));
    const m: u64 = @intCast(@mod(@divTrunc(key, 100), 100));
    const d: u64 = @intCast(@mod(key, 100));
    return std.fmt.bufPrint(buf, "{d:0>4}-{d:0>2}-{d:0>2}", .{ y, m, d }) catch "";
}

/// minDate/maxDate merge (diffed updates carry only the changed key); the
/// empty string clears a bound. Enforcement lives in cbCalendarDaySelected —
/// GtkCalendar has no native range clamp.
fn ndCalendarSetLimits(cal: *gtk.Calendar, min_s: ?[]const u8, max_s: ?[]const u8) void {
    if (min_s == null and max_s == null) return;
    const gop = calendar_limits.getOrPut(events_gpa, @intFromPtr(cal)) catch return;
    if (!gop.found_existing) {
        gop.value_ptr.* = .{};
        _ = gtk.Widget.signals.destroy.connect(cal.as(gtk.Widget), ?*anyopaque, &cbCalendarDestroyed, null, .{});
    }
    if (min_s) |s| gop.value_ptr.min = if (s.len == 0) null else ndDateKeyFromIso(s);
    if (max_s) |s| gop.value_ptr.max = if (s.len == 0) null else ndDateKeyFromIso(s);
}

// ---- Video (GtkVideo) media-module detection + src routing ----
var video_media_checked = false;
var video_media_available = false;

/// GtkMediaFile's real backend ships separately on some distros
/// (gtk4-media-gstreamer & co.); with none installed GTK falls back to its
/// no-op "GtkNoMediaFile" implementation (plus GTK's own one-time warning).
fn ndVideoMediaAvailable() bool {
    if (video_media_checked) return video_media_available;
    video_media_checked = true;
    const mf = gtk.MediaFile.new();
    defer gobject.Object.unref(asObject(mf));
    const instance: *gobject.TypeInstance = @ptrCast(@alignCast(mf));
    const type_name = std.mem.span(gobject.typeNameFromInstance(instance));
    video_media_available = !std.mem.eql(u8, type_name, "GtkNoMediaFile");
    return video_media_available;
}

/// GFile wraps both plain paths and URIs (there is no gtk_video_new_for_uri).
fn ndVideoSetSrc(video: *gtk.Video, src: [:0]const u8) void {
    if (src.len == 0) {
        gtk.Video.setFile(video, null);
        return;
    }
    const file = if (std.mem.indexOf(u8, src, "://") != null) gio.File.newForUri(src) else gio.File.newForPath(src);
    gtk.Video.setFile(video, file); // property setter refs; drop ours
    gobject.Object.unref(@ptrCast(@alignCast(file)));
}

// ---- cmux-parity-polish-2: Paned (draggable two-child split, distinct from
// SplitView's collapsible-sidebar AdwOverlaySplitView) ----
const ND_PANED_PENDING_FRACTION = "nd-paned-pending-fraction";
const ND_PANED_TICK_ID = "nd-paned-tick-id";
const ND_PANED_DEBOUNCE_ID = "nd-paned-debounce-id";
const ND_PANED_NODE_ID = "nd-paned-node-id";

/// `position` is a 0..1 fraction of the total size, but GtkPaned's own
/// `position` property is a pixel offset from the left/top — converting
/// needs the widget's current allocation, which is 0 until the first layout
/// pass. Applied immediately once allocated (the update path); otherwise
/// stashed for the first-layout tick retry (cbPanedMapped/ndPanedTickApply)
/// to replay once real geometry exists.
fn ndPanedApplyPosition(paned: *gtk.Paned, frac: f64) void {
    const widget = paned.as(gtk.Widget);
    const horizontal = gtk.Orientable.getOrientation(paned.as(gtk.Orientable)) == .horizontal;
    const total = if (horizontal) gtk.Widget.getAllocatedWidth(widget) else gtk.Widget.getAllocatedHeight(widget);
    if (total <= 0) {
        // +1: a bit-cast 0.0 fraction is the null pointer, which qdata can't
        // tell apart from "no data set" — offset by one, undo it on read.
        gobject.Object.setData(asObject(widget), ND_PANED_PENDING_FRACTION, @ptrFromInt(@as(usize, @bitCast(frac)) + 1));
        // An already-mapped widget gets no further "map", so kick the retry here.
        if (gtk.Widget.getMapped(widget) != 0) ndPanedEnsureTick(widget);
        return;
    }
    blockEcho(asObject(widget));
    gtk.Paned.setPosition(paned, @intFromFloat(@round(frac * @as(f64, @floatFromInt(total)))));
    unblockEcho(asObject(widget));
}

/// GTK4 emits "map" BEFORE the first size-allocate, so the allocation is
/// still 0 here and the stashed fraction can't be converted yet. Start a
/// per-frame tick retry instead of applying directly.
fn cbPanedMapped(obj: *gobject.Object, _: ?*anyopaque) callconv(.c) void {
    if (gobject.Object.getData(obj, ND_PANED_PENDING_FRACTION) == null) return;
    ndPanedEnsureTick(@ptrCast(@alignCast(obj)));
}

fn ndPanedEnsureTick(widget: *gtk.Widget) void {
    const obj = asObject(widget);
    if (gobject.Object.getData(obj, ND_PANED_TICK_ID) != null) return;
    const id = gtk.Widget.addTickCallback(widget, &ndPanedTickApply, null, null);
    gobject.Object.setData(obj, ND_PANED_TICK_ID, @ptrFromInt(@as(usize, id))); // tick ids start at 1
}

/// Applies the stashed fraction on the first frame with a real allocation,
/// then removes itself. GTK drops live tick callbacks when the widget is
/// destroyed, so no extra teardown bookkeeping is needed.
fn ndPanedTickApply(widget: *gtk.Widget, _: *gdk.FrameClock, _: ?*anyopaque) callconv(.c) c_int {
    const obj = asObject(widget);
    const raw = gobject.Object.getData(obj, ND_PANED_PENDING_FRACTION) orelse {
        gobject.Object.setData(obj, ND_PANED_TICK_ID, null);
        return 0; // G_SOURCE_REMOVE: the update path applied it meanwhile
    };
    const paned: *gtk.Paned = @ptrCast(@alignCast(widget));
    const horizontal = gtk.Orientable.getOrientation(paned.as(gtk.Orientable)) == .horizontal;
    const total = if (horizontal) gtk.Widget.getAllocatedWidth(widget) else gtk.Widget.getAllocatedHeight(widget);
    if (total <= 0) return 1; // G_SOURCE_CONTINUE: not laid out yet
    gobject.Object.setData(obj, ND_PANED_PENDING_FRACTION, null);
    gobject.Object.setData(obj, ND_PANED_TICK_ID, null);
    const frac: f64 = @bitCast(@as(usize, @intFromPtr(raw)) - 1); // undo the +1 offset from setData
    ndPanedApplyPosition(paned, frac);
    return 0; // G_SOURCE_REMOVE
}

/// Fired 150ms after the last notify::position (cbPanedPositionChanged's
/// debounce) — reads the settled divider position back as a 0..1 fraction
/// and emits onPositionChanged. `user_data` holds the ref cbPanedPositionChanged
/// took to keep the widget alive across the wait; always released here.
fn ndPanedEmitPosition(user_data: ?*anyopaque) callconv(.c) c_int {
    const obj: *gobject.Object = @ptrCast(@alignCast(user_data.?));
    defer gobject.Object.unref(obj);
    gobject.Object.setData(obj, ND_PANED_DEBOUNCE_ID, null);
    const node_raw = gobject.Object.getData(obj, ND_PANED_NODE_ID) orelse return 0;
    const node_id: u32 = @intCast(@intFromPtr(node_raw));
    const paned: *gtk.Paned = @ptrCast(@alignCast(obj));
    const widget = paned.as(gtk.Widget);
    const horizontal = gtk.Orientable.getOrientation(paned.as(gtk.Orientable)) == .horizontal;
    const total = if (horizontal) gtk.Widget.getAllocatedWidth(widget) else gtk.Widget.getAllocatedHeight(widget);
    if (total <= 0) return 0; // G_SOURCE_REMOVE
    const frac = @as(f64, @floatFromInt(gtk.Paned.getPosition(paned))) / @as(f64, @floatFromInt(total));
    if (emit) |f| f(node_id, "positionChanged", .{ .position = frac });
    return 0; // G_SOURCE_REMOVE
}

/// Cross-cutting removal hook (AppKit peer: ndPanedTeardown in
/// PanedController.swift): a removed `<paned>`'s pending 150ms settle timer
/// (cbPanedPositionChanged) would otherwise outlive the widget's place in
/// the tree and fire against stale geometry. Cancels it and drops the ref
/// the timer held. No-op for every other widget kind.
pub fn ndPanedStructuralTeardown(child: *gtk.Widget) void {
    if (!gobject.ext.isA(child, gtk.Paned)) return;
    const obj = asObject(child);
    const raw = gobject.Object.getData(obj, ND_PANED_DEBOUNCE_ID) orelse return;
    _ = glib.Source.remove(@intCast(@intFromPtr(raw)));
    gobject.Object.setData(obj, ND_PANED_DEBOUNCE_ID, null);
    gobject.Object.unref(obj); // the cancelled timer's ref
}

/// The GTK create dispatcher. `dupeZ` turns a wire string into a NUL-
/// terminated GTK string using the backend arena (passed by the caller).
pub fn create(
    app: *gtk.Application,
    kind: []const u8,
    props: ?std.json.Value,
    dupeZ: *const fn ([]const u8) [:0]const u8,
    the_window: *?*gtk.Window,
) !*gtk.Widget {
    if (std.mem.eql(u8, kind, "Window")) {
        const w: c_int = @intCast(propInt(props, "defaultWidth") orelse 480);
        const h: c_int = @intCast(propInt(props, "defaultHeight") orelse 320);
        return ndtabs_gtk.createWindow(app, propStr(props, "tabGroup"), propStr(props, "title"), w, h, the_window, dupeZ);
    } else if (std.mem.eql(u8, kind, "Box")) {
        const vertical = if (propStr(props, "orientation")) |o| std.mem.eql(u8, o, "vertical") else true;
        const orientation: gtk.Orientation = if (vertical) .vertical else .horizontal;
        const spacing: c_int = @intCast(propInt(props, "spacing") orelse 0);
        const box = gtk.Box.new(orientation, spacing);
        return box.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Label")) {
        const text = propStr(props, "text") orelse "";
        const label = gtk.Label.new(dupeZ(text));
        // GtkLabel defaults to centered text when it is allocated extra width.
        // Native form rows expect their expanding title labels to stay leading-aligned.
        gtk.Label.setXalign(label, 0.0);
        if (propBool(props, "ellipsize") orelse false) {
            // The label must stop dictating its parent's width: .end caps the
            // minimum at one ellipsis, max-width-chars(1) caps the natural
            // request too, and hexpand still fills whatever the row has.
            gtk.Label.setEllipsize(label, .end);
            gtk.Label.setMaxWidthChars(label, 1);
            gtk.Widget.setHexpand(label.as(gtk.Widget), 1);
        }
        return label.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Button")) {
        const lbl = propStr(props, "label") orelse "Button";
        var button: *gtk.Button = undefined;
        if (propStr(props, "iconName")) |icon| {
            if (lbl.len == 0) {
                button = gtk.Button.new();
                gtk.Button.setIconName(button, ndicons.symbolic(dupeZ(icon)));
            } else {
                button = gtk.Button.new();
                const content = adw.ButtonContent.new();
                adw.ButtonContent.setIconName(content, ndicons.symbolic(dupeZ(icon)));
                adw.ButtonContent.setLabel(content, dupeZ(lbl));
                gtk.Button.setChild(button, content.as(gtk.Widget));
            }
        } else {
            button = gtk.Button.newWithLabel(dupeZ(lbl));
        }
        const label_align = propStr(props, "labelAlign") orelse "center";
        if (!std.mem.eql(u8, label_align, "center")) {
            if (gtk.Button.getChild(button)) |child| {
                const halign: gtk.Align = if (std.mem.eql(u8, label_align, "start")) .start else .end;
                gtk.Widget.setHalign(child, halign);
                if (gobject.ext.isA(child, gtk.Label)) {
                    const xalign: f32 = if (std.mem.eql(u8, label_align, "start")) 0.0 else 1.0;
                    gtk.Label.setXalign(@ptrCast(@alignCast(child)), xalign);
                }
            }
        }
        if (propBool(props, "ellipsize") orelse false) {
            // can-shrink ellipsizes the title instead of forcing the button's
            // min width to the full text (GTK 4.12+ / libadwaita 1.4+).
            gtk.Button.setCanShrink(button, 1);
            if (gtk.Button.getChild(button)) |child| {
                if (gobject.ext.isA(child, adw.ButtonContent)) adw.ButtonContent.setCanShrink(@ptrCast(@alignCast(child)), 1);
            }
        }
        if (propStr(props, "tooltip")) |tt| gtk.Widget.setTooltipText(button.as(gtk.Widget), dupeZ(tt));
        return button.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "TextInput")) {
        const entry = gtk.Entry.new();
        const editable = entry.as(gtk.Editable);
        if (propStr(props, "text")) |t| { if (t.len > 0) gtk.Editable.setText(editable, dupeZ(t)); }
        if (propStr(props, "placeholder")) |p| gtk.Entry.setPlaceholderText(entry, dupeZ(p));
        if (propBool(props, "editable")) |e| gtk.Editable.setEditable(editable, @intFromBool(e));
        return entry.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "TextArea")) {
        const view = gtk.TextView.new();
        const buf = gtk.TextView.getBuffer(view);
        if (propStr(props, "text")) |t| { if (t.len > 0) gtk.TextBuffer.setText(buf, dupeZ(t), -1); }
        if (propInt(props, "minContentHeight")) |h| { if (h > 0) gtk.Widget.setSizeRequest(view.as(gtk.Widget), -1, @intCast(h)); }
        return view.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Checkbox")) {
        const cb = gtk.CheckButton.newWithLabel(dupeZ(propStr(props, "label") orelse ""));
        if (propBool(props, "checked") orelse false) gtk.CheckButton.setActive(cb, 1);
        return cb.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Radio")) {
        const cb = gtk.CheckButton.newWithLabel(dupeZ(propStr(props, "label") orelse ""));
        if (propStr(props, "group")) |g| {
            std.debug.assert(events_ready); // initEvents runs before any create (runtime.zig startup order)
            if (radio_groups.get(g)) |first| {
                gtk.CheckButton.setGroup(cb, first);
            } else if (events_gpa.dupe(u8, g)) |key| {
                radio_groups.put(events_gpa, key, cb) catch events_gpa.free(key);
                // Evict the entry when this anchor dies (see cbRadioGroupDestroyed).
                _ = gtk.Widget.signals.destroy.connect(cb.as(gtk.Widget), ?*anyopaque, &cbRadioGroupDestroyed, null, .{});
            } else |_| {} // OOM: skip anchoring; this radio forms its own group
        } else {
            std.debug.print("ND_WARN Radio without group prop\n", .{});
        }
        if (propBool(props, "checked") orelse false) gtk.CheckButton.setActive(cb, 1);
        return cb.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Select")) {
        const sl = gtk.StringList.new(null);
        if (propArray(props, "options")) |arr| {
            for (arr.items) |item| {
                if (item == .string) gtk.StringList.append(sl, dupeZ(item.string));
            }
        }
        const dd = gtk.DropDown.new(sl.as(gio.ListModel), null); // transfer-full: DropDown owns the model
        const idx = propInt(props, "selectedIndex") orelse 0;
        if (idx > 0) gtk.DropDown.setSelected(dd, @intCast(idx));
        return dd.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Slider")) {
        const min = propFloat(props, "min") orelse 0;
        const max = propFloat(props, "max") orelse 100;
        const step = propFloat(props, "step") orelse 1;
        const vertical = if (propStr(props, "orientation")) |o| std.mem.eql(u8, o, "vertical") else false;
        const scale = gtk.Scale.newWithRange(if (vertical) .vertical else .horizontal, min, max, step);
        gtk.Range.setValue(scale.as(gtk.Range), propFloat(props, "value") orelse 0);
        return scale.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "ProgressBar")) {
        const pb = gtk.ProgressBar.new();
        if (propFloat(props, "fraction")) |f| gtk.ProgressBar.setFraction(pb, f);
        return pb.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Image")) {
        const img = gtk.Image.new();
        if (propStr(props, "path")) |p| {
            gtk.Image.setFromFile(img, dupeZ(p));
        } else if (propStr(props, "iconName")) |n| {
            gtk.Image.setFromIconName(img, ndicons.symbolic(dupeZ(n)));
        }
        return img.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "ScrollView")) {
        const sw = gtk.ScrolledWindow.new();
        if (propInt(props, "minContentHeight")) |h| { if (h > 0) gtk.ScrolledWindow.setMinContentHeight(sw, @intCast(h)); }
        // hscroll=never clamps content to the viewport width instead of
        // growing a horizontal scrollbar under vertically-scrolling lists.
        if (propStr(props, "hscroll")) |h| {
            if (std.mem.eql(u8, h, "never")) gtk.ScrolledWindow.setPolicy(sw, .never, .automatic);
        }
        return sw.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Separator")) {
        const vertical = if (propStr(props, "orientation")) |o| std.mem.eql(u8, o, "vertical") else false;
        const sep = gtk.Separator.new(if (vertical) .vertical else .horizontal);
        return sep.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Spinner")) {
        const sp = gtk.Spinner.new();
        if (propBool(props, "spinning") orelse true) gtk.Spinner.setSpinning(sp, 1);
        return sp.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "TabView")) {
        // selectedIndex is ignored at create: pages attach afterwards (M5b-D4).
        const nb = gtk.Notebook.new();
        return nb.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Grid")) {
        const grid = gtk.Grid.new();
        return grid.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "ListView")) {
        const strv = buildStrv(propArray(props, "items"), dupeZ); // O(n) bulk build, not per-item append
        defer std.heap.page_allocator.free(strv);
        const model = gtk.StringList.new(@ptrCast(strv.ptr));
        const selection = gtk.SingleSelection.new(model.as(gio.ListModel)); // transfer-full: selection owns model
        const sel_idx = propInt(props, "selectedIndex") orelse -1;
        if (sel_idx >= 0) gtk.SingleSelection.setSelected(selection, @intCast(sel_idx));
        const factory = gtk.SignalListItemFactory.new();
        _ = gobject.signalConnectData(asObject(factory), "setup", @ptrCast(&lvSetup), null, null, .{});
        _ = gobject.signalConnectData(asObject(factory), "bind", @ptrCast(&lvBind), null, null, .{});
        const list = gtk.ListView.new(selection.as(gtk.SelectionModel), factory.as(gtk.ListItemFactory)); // transfer-full: list owns selection+factory
        const sw = gtk.ScrolledWindow.new(); // M5c-D3: ListView needs a scroller
        gtk.ScrolledWindow.setChild(sw, list.as(gtk.Widget));
        return sw.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "WebView")) {
        // Real WebKitGTK surface when libwebkitgtk-6.0 is dlopen-able at
        // runtime; placeholder label otherwise (M5b-D7: no hard link dep).
        const url: ?[*:0]const u8 = if (propStr(props, "url")) |u| dupeZ(u).ptr else null;
        return ndweb_gtk.create(url);
    } else if (std.mem.eql(u8, kind, "NativeView")) {
        const view_kind = propStr(props, "viewKind") orelse "";
        const props_json = propStr(props, "props") orelse "{}";
        if (nd_plugin.viewCreate(view_kind, props_json)) |v| {
            const nv: *gtk.Widget = @ptrCast(@alignCast(v));
            gobject.Object.setData(asObject(nv), "nd-view-kind", @ptrCast(@constCast(dupeZ(view_kind).ptr)));
            return nv;
        }
        std.debug.print("ND_WARN nativeView: no module registered viewKind={s}; rendering empty box\n", .{view_kind});
        return gtk.Box.new(.vertical, 0).as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "SplitView")) {
        const sv = adw.OverlaySplitView.new();
        if (propFloat(props, "sidebarWidth")) |sw| { if (sw > 0) adw.OverlaySplitView.setSidebarWidthFraction(sv, sw); }
        if (propBool(props, "collapsed")) |c| adw.OverlaySplitView.setCollapsed(sv, @intFromBool(c));
        if (propFloat(props, "listWidth")) |lw| { if (lw > 0) split_list_widths.put(events_gpa, @intFromPtr(sv), lw) catch {}; }
        return sv.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "HeaderBar")) {
        const hb = adw.HeaderBar.new();
        // Matching the AppKit shell: an absent/empty `title` shows NO title.
        // AdwHeaderBar's default title widget would otherwise fall back to
        // the window title, which the app never declared on this header.
        const t = propStr(props, "title") orelse "";
        if (t.len > 0) {
            const wt = adw.WindowTitle.new(dupeZ(t), "");
            adw.HeaderBar.setTitleWidget(hb, wt.as(gtk.Widget));
        } else {
            adw.HeaderBar.setShowTitle(hb, 0);
        }
        ndMenuNoteHeaderBar(hb); // M13: track for primary-menu-button placement (no-op sans <menubar>)
        ndHeaderBarApplyNav(hb, propBool(props, "canGoBack"), propBool(props, "canGoForward"));
        return hb.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "ToolbarView")) {
        const tv = adw.ToolbarView.new();
        return tv.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "SearchInput")) {
        const search = gtk.SearchEntry.new();
        const editable = search.as(gtk.Editable);
        if (propStr(props, "text")) |t| { if (t.len > 0) gtk.Editable.setText(editable, dupeZ(t)); }
        if (propStr(props, "placeholder")) |p| gtk.SearchEntry.setPlaceholderText(search, dupeZ(p));
        return search.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "SourceList")) {
        const box = gtk.ListBox.new();
        gtk.ListBox.setSelectionMode(box, .browse);
        gtk.ListBox.setActivateOnSingleClick(box, 0);
        gtk.Widget.addCssClass(box.as(gtk.Widget), "navigation-sidebar");
        ndBuildSourceRows(box, propArray(props, "items"), dupeZ);
        const sel_idx = propInt(props, "selectedIndex") orelse -1;
        if (sel_idx >= 0) { if (gtk.ListBox.getRowAtIndex(box, @intCast(sel_idx))) |r| gtk.ListBox.selectRow(box, r); }
        const sw = gtk.ScrolledWindow.new();
        gtk.ScrolledWindow.setChild(sw, box.as(gtk.Widget));
        return sw.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Menubar")) {
        const defaults = propBool(props, "defaults") orelse true;
        return ndMenubarCreate(app, the_window.*, defaults);
    } else if (std.mem.eql(u8, kind, "Menu")) {
        const label = dupeZ(propStr(props, "label") orelse "");
        return ndMenuCreate(app, label);
    } else if (std.mem.eql(u8, kind, "MenuItem")) {
        return ndMenuItemCreate(app, props, dupeZ);
    } else if (std.mem.eql(u8, kind, "SettingsGroup")) {
        const spacing: c_int = @intCast(propInt(props, "spacing") orelse 0);
        const box = gtk.Box.new(.vertical, spacing);
        gtk.Widget.addCssClass(box.as(gtk.Widget), "card");
        return box.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Switch")) {
        const sw = gtk.Switch.new();
        gtk.Switch.setActive(sw, @intFromBool(propBool(props, "checked") orelse false));
        return sw.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "ToggleButton")) {
        const lbl = propStr(props, "label") orelse "";
        const tb = gtk.ToggleButton.new();
        if (propStr(props, "iconName")) |icon| {
            if (lbl.len == 0) {
                gtk.Button.setIconName(tb.as(gtk.Button), ndicons.symbolic(dupeZ(icon)));
            } else {
                const content = adw.ButtonContent.new();
                adw.ButtonContent.setIconName(content, ndicons.symbolic(dupeZ(icon)));
                adw.ButtonContent.setLabel(content, dupeZ(lbl));
                gtk.Button.setChild(tb.as(gtk.Button), content.as(gtk.Widget));
            }
        } else {
            gtk.Button.setLabel(tb.as(gtk.Button), dupeZ(lbl));
        }
        if (propBool(props, "active") orelse false) gtk.ToggleButton.setActive(tb, 1);
        return tb.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "SegmentedControl")) {
        // AdwToggleGroup (adw 1.7+): exclusive option selection within a view
        // (view switchers own page navigation). options are create-only,
        // matching Select.options.
        const group = adw.ToggleGroup.new();
        if (propArray(props, "options")) |arr| {
            for (arr.items) |item| {
                if (item != .string) continue;
                const toggle = adw.Toggle.new();
                adw.Toggle.setLabel(toggle, dupeZ(item.string));
                adw.ToggleGroup.add(group, toggle);
            }
        }
        const idx = propInt(props, "selectedIndex") orelse 0;
        if (idx > 0) adw.ToggleGroup.setActive(group, @intCast(idx));
        return group.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "NumberInput")) {
        const min = propFloat(props, "min") orelse 0;
        const max = propFloat(props, "max") orelse 100;
        const step = propFloat(props, "step") orelse 1;
        const spin = gtk.SpinButton.newWithRange(min, max, step);
        gtk.SpinButton.setDigits(spin, @intCast(propInt(props, "digits") orelse 0));
        gtk.SpinButton.setWrap(spin, @intFromBool(propBool(props, "wraps") orelse false));
        gtk.SpinButton.setValue(spin, propFloat(props, "value") orelse 0);
        return spin.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "LinkButton")) {
        const uri = propStr(props, "uri") orelse "";
        const lbl = propStr(props, "label") orelse "";
        const lb = gtk.LinkButton.newWithLabel(dupeZ(uri), if (lbl.len > 0) dupeZ(lbl).ptr else null); // null label: GTK shows the URI
        if (propBool(props, "visited") orelse false) gtk.LinkButton.setVisited(lb, 1);
        if (propBool(props, "openExternal") orelse false) gobject.Object.setData(asObject(lb), "nd-open-external", @ptrFromInt(1));
        return lb.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "LevelIndicator")) {
        const min = propFloat(props, "min") orelse 0;
        const max = propFloat(props, "max") orelse 1;
        const bar = gtk.LevelBar.newForInterval(min, max);
        if (propBool(props, "discrete") orelse false) gtk.LevelBar.setMode(bar, .discrete);
        gtk.LevelBar.setValue(bar, propFloat(props, "value") orelse 0);
        ndLevelBarApplyOffsets(bar, propFloat(props, "warningValue"), propFloat(props, "criticalValue"));
        return bar.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "ColorPicker")) {
        // GtkColorDialogButton (GTK 4.10+); the button stays insensitive
        // until a GtkColorDialog is set, so it is set unconditionally.
        const dialog = gtk.ColorDialog.new();
        gtk.ColorDialog.setWithAlpha(dialog, @intFromBool(propBool(props, "supportsAlpha") orelse false));
        const btn = gtk.ColorDialogButton.new(dialog); // transfer-full: button owns the dialog
        var rgba: gdk.RGBA = undefined;
        if (gdk.RGBA.parse(&rgba, dupeZ(propStr(props, "value") orelse "#000000")) != 0) gtk.ColorDialogButton.setRgba(btn, &rgba);
        return btn.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Banner")) {
        const banner = adw.Banner.new(dupeZ(propStr(props, "title") orelse ""));
        if (propStr(props, "buttonLabel")) |bl| adw.Banner.setButtonLabel(banner, dupeZ(bl));
        if (propBool(props, "revealed") orelse false) adw.Banner.setRevealed(banner, 1);
        return banner.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "MenuButton")) {
        const btn = gtk.MenuButton.new();
        const lbl = propStr(props, "label") orelse "";
        if (propStr(props, "iconName")) |icon| {
            if (lbl.len == 0) {
                gtk.MenuButton.setIconName(btn, ndicons.symbolic(dupeZ(icon)));
            } else {
                // icon+label both set: a plain icon_name/label assignment can only
                // show one of them, so give the button a custom AdwButtonContent
                // child (mirrors Button's create arm) and force the dropdown arrow
                // back on since a custom child would otherwise hide it.
                const content = adw.ButtonContent.new();
                adw.ButtonContent.setIconName(content, ndicons.symbolic(dupeZ(icon)));
                adw.ButtonContent.setLabel(content, dupeZ(lbl));
                gtk.MenuButton.setChild(btn, content.as(gtk.Widget));
                gtk.MenuButton.setAlwaysShowArrow(btn, 1);
            }
        } else if (lbl.len > 0) {
            gtk.MenuButton.setLabel(btn, dupeZ(lbl));
        }
        // Content-sized like Button/ToggleButton, not stretched to fill a
        // parent GtkBox — GtkMenuButton's composite internals otherwise
        // compute hexpand=true from its own child.
        gtk.Widget.setHexpand(btn.as(gtk.Widget), 0);
        gtk.Widget.setHalign(btn.as(gtk.Widget), .start);
        // Menu/MenuItem children arrive via the MenuButton structural arm
        // (ndMenuOwnerAppend) and become this button's GMenuModel.
        _ = gtk.Widget.signals.destroy.connect(btn.as(gtk.Widget), ?*anyopaque, &cbMenuOwnerDestroyed, null, .{});
        return btn.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "SplitButton")) {
        const btn = adw.SplitButton.new();
        const lbl = propStr(props, "label") orelse "";
        if (propStr(props, "iconName")) |icon| {
            if (lbl.len == 0) {
                adw.SplitButton.setIconName(btn, ndicons.symbolic(dupeZ(icon)));
            } else {
                // icon+label both set: AdwSplitButton's label/icon_name/child
                // properties are mutually exclusive (setting one clears the other
                // two), so a custom AdwButtonContent child is the only way to show
                // both at once (mirrors Button's create arm). The dropdown arrow is
                // its own separate button on AdwSplitButton, so it always survives.
                const content = adw.ButtonContent.new();
                adw.ButtonContent.setIconName(content, ndicons.symbolic(dupeZ(icon)));
                adw.ButtonContent.setLabel(content, dupeZ(lbl));
                adw.SplitButton.setChild(btn, content.as(gtk.Widget));
            }
        } else if (lbl.len > 0) {
            adw.SplitButton.setLabel(btn, dupeZ(lbl));
        }
        // Content-sized like Button/ToggleButton, not stretched to fill a
        // parent GtkBox — AdwSplitButton's composite internals otherwise
        // compute hexpand=true from its own children.
        gtk.Widget.setHexpand(btn.as(gtk.Widget), 0);
        gtk.Widget.setHalign(btn.as(gtk.Widget), .start);
        _ = gtk.Widget.signals.destroy.connect(btn.as(gtk.Widget), ?*anyopaque, &cbMenuOwnerDestroyed, null, .{});
        return btn.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Popover")) {
        const pop = gtk.Popover.new();
        gtk.Popover.setAutohide(pop, 1); // transient: click-outside dismisses (closed syncs `open` back)
        gtk.Popover.setPosition(pop, ndPositionFromString(propStr(props, "position") orelse "top"));
        // Anchoring happens when the tree parent appends this node (see the
        // ndPopoverAttach structural guard); a create-time open waits there.
        if (propBool(props, "open") orelse false) gobject.Object.setData(asObject(pop), ND_POPOVER_PENDING_OPEN, @ptrFromInt(1));
        return pop.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Expander")) {
        const ex = gtk.Expander.new(dupeZ(propStr(props, "label") orelse ""));
        if (propBool(props, "expanded") orelse false) gtk.Expander.setExpanded(ex, 1);
        return ex.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "StatusPage")) {
        const page = adw.StatusPage.new();
        if (propStr(props, "iconName")) |ic| adw.StatusPage.setIconName(page, ndicons.symbolic(dupeZ(ic)));
        adw.StatusPage.setTitle(page, dupeZ(propStr(props, "title") orelse ""));
        if (propStr(props, "description")) |d| adw.StatusPage.setDescription(page, dupeZ(d));
        // Multi children (action buttons) fan into one wrapping GtkBox set as
        // the page's single child — same move ToolbarView/SettingsGroup make.
        const box = gtk.Box.new(.vertical, 12);
        gtk.Widget.setHalign(box.as(gtk.Widget), .center);
        adw.StatusPage.setChild(page, box.as(gtk.Widget));
        return page.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "ToastOverlay")) {
        const overlay = adw.ToastOverlay.new();
        return overlay.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "DatePicker")) {
        // displayStyle "field" has no GTK backing yet — the inline calendar
        // renders for both styles (documented asymmetry; AppKit honors it).
        const cal = gtk.Calendar.new();
        if (propStr(props, "value")) |v| {
            if (ndDateKeyFromIso(v)) |key| ndCalendarSelectKey(cal, key);
        }
        ndCalendarSetLimits(cal, propStr(props, "minDate"), propStr(props, "maxDate"));
        return cal.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Table")) {
        return ndtable_gtk.create(props, dupeZ);
    } else if (std.mem.eql(u8, kind, "TreeView")) {
        return ndtree_gtk.create(props, dupeZ);
    } else if (std.mem.eql(u8, kind, "FontPicker")) {
        const dialog = gtk.FontDialog.new();
        const btn = gtk.FontDialogButton.new(dialog); // transfer-full: button owns the dialog
        const desc = pango.FontDescription.fromString(dupeZ(propStr(props, "value") orelse "Sans 12")); // Pango font description syntax is the canonical wire value
        gtk.FontDialogButton.setFontDesc(btn, desc);
        pango.FontDescription.free(desc); // setFontDesc copies
        return btn.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Video")) {
        if (!ndVideoMediaAvailable()) {
            // GtkMediaFile's backend is a separate package on some distros
            // (e.g. gtk4-media-gstreamer) — degrade to a placeholder, like
            // WebView does without webkitgtk.
            std.debug.print("ND_WARN Video unavailable (no GTK media module; install the gstreamer GTK media backend); rendering placeholder label\n", .{});
            const label = gtk.Label.new("Video unavailable (GTK media module not installed)");
            return label.as(gtk.Widget);
        }
        const video = gtk.Video.new();
        // A video is a content surface: expand like WebView does.
        gtk.Widget.setHexpand(video.as(gtk.Widget), 1);
        gtk.Widget.setVexpand(video.as(gtk.Widget), 1);
        gtk.Video.setAutoplay(video, @intFromBool(propBool(props, "autoplay") orelse false));
        gtk.Video.setLoop(video, @intFromBool(propBool(props, "loop") orelse false));
        // `controls` is accepted but ignored: GtkVideo's overlaid controls
        // have no toggle (AppKit's AVPlayerView honors it).
        if (propStr(props, "src")) |s| { if (s.len > 0) ndVideoSetSrc(video, dupeZ(s)); }
        return video.as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "TrayItem")) {
        // ND_PLATFORM_NOOP(TrayItem): not available on this platform — invisible empty box by design.
        return gtk.Box.new(.vertical, 0).as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "ShareButton")) {
        // ND_PLATFORM_NOOP(ShareButton): not available on this platform — invisible empty box by design.
        return gtk.Box.new(.vertical, 0).as(gtk.Widget);
    } else if (std.mem.eql(u8, kind, "Terminal")) {
        const font_size: c_int = @intCast(propInt(props, "fontSize") orelse 13);
        const font_family: ?[*:0]const u8 = if (propStr(props, "fontFamily")) |f| dupeZ(f).ptr else null;
        const palette: ?[*:0]const u8 = if (propStr(props, "palette")) |p| dupeZ(p).ptr else null;
        const fg: [*:0]const u8 = dupeZ(propStr(props, "foreground") orelse "#cccccc").ptr;
        const bg: [*:0]const u8 = dupeZ(propStr(props, "background") orelse "#000000").ptr;
        const cols: u16 = @intCast(propInt(props, "cols") orelse 80);
        const rows: u16 = @intCast(propInt(props, "rows") orelse 24);
        // SEAM: ndterm_gtk create/createRemote signatures are the published contract with src/gtk/terminal.zig (package nd-terminal-surfaces) — keep both sides byte-for-byte in sync.
        //   create(command: ?[*:0]const u8, cwd: ?[*:0]const u8, font_size: c_int, font_family: ?[*:0]const u8, palette: ?[*:0]const u8, foreground: [*:0]const u8, background: [*:0]const u8, cols: u16, rows: u16) *gtk.Widget
        //   createRemote(host: [*:0]const u8, port: u16, session_id: [*:0]const u8, ticket: [*:0]const u8, font_size: c_int, font_family: ?[*:0]const u8, palette: ?[*:0]const u8, foreground: [*:0]const u8, background: [*:0]const u8, cols: u16, rows: u16) *gtk.Widget
        if (propBool(props, "remote") orelse false) {
            const host: [*:0]const u8 = if (propStr(props, "host")) |h| dupeZ(h).ptr else "127.0.0.1";
            const port: u16 = @intCast(propInt(props, "port") orelse 4618);
            const sid: [*:0]const u8 = if (propStr(props, "sessionId")) |s| dupeZ(s).ptr else "";
            const ticket: [*:0]const u8 = if (propStr(props, "ticket")) |t| dupeZ(t).ptr else "";
            return ndterm_gtk.createRemote(host, port, sid, ticket, font_size, font_family, palette, fg, bg, cols, rows);
        }
        const command: ?[*:0]const u8 = if (propStr(props, "command")) |c| dupeZ(c).ptr else null;
        const cwd: ?[*:0]const u8 = if (propStr(props, "cwd")) |c| dupeZ(c).ptr else null;
        return ndterm_gtk.create(command, cwd, font_size, font_family, palette, fg, bg, cols, rows);
    } else if (std.mem.eql(u8, kind, "Paned")) {
        const vertical = if (propStr(props, "orientation")) |o| std.mem.eql(u8, o, "vertical") else false;
        const orientation: gtk.Orientation = if (vertical) .vertical else .horizontal;
        const paned = gtk.Paned.new(orientation);
        const frac = propFloat(props, "position") orelse 0.5;
        // +1: 0.0 bit-casts to the null pointer, indistinguishable from unset qdata (see cbPanedMapped).
        gobject.Object.setData(asObject(paned), ND_PANED_PENDING_FRACTION, @ptrFromInt(@as(usize, @bitCast(frac)) + 1));
        _ = gobject.signalConnectData(asObject(paned), "map", @ptrCast(&cbPanedMapped), null, null, .{});
        return paned.as(gtk.Widget);
    }
    std.debug.print("ND_WARN unknown widget kind={s}\n", .{kind});
    return error.UnknownWidget;
}

/// The GTK update dispatcher for createAndUpdate props.
pub fn applyProps(widget: *gtk.Widget, kind: []const u8, props: ?std.json.Value, dupeZ: *const fn ([]const u8) [:0]const u8) void {
    if (std.mem.eql(u8, kind, "Window")) {
        if (propStr(props, "title")) |t| ndtabs_gtk.setTitle(widget, dupeZ(t));
    } else if (std.mem.eql(u8, kind, "Box")) {
        if (propInt(props, "spacing")) |s| {
            const box: *gtk.Box = @ptrCast(@alignCast(widget));
            gtk.Box.setSpacing(box, @intCast(s));
        }
    } else if (std.mem.eql(u8, kind, "Button")) {
        if (propStr(props, "tooltip")) |tt| gtk.Widget.setTooltipText(widget, dupeZ(tt));
    } else if (std.mem.eql(u8, kind, "TextInput")) {
        if (propStr(props, "text")) |t| {
            const editable = @as(*gtk.Entry, @ptrCast(@alignCast(widget))).as(gtk.Editable);
            const cur = std.mem.span(gtk.Editable.getText(editable));
            if (!std.mem.eql(u8, cur, t)) {
                blockEcho(asObject(widget));
                gtk.Editable.setText(editable, dupeZ(t));
                unblockEcho(asObject(widget));
            }
        }
        if (propStr(props, "placeholder")) |p_| gtk.Entry.setPlaceholderText(@ptrCast(@alignCast(widget)), dupeZ(p_));
        if (propBool(props, "editable")) |e| gtk.Editable.setEditable(@as(*gtk.Entry, @ptrCast(@alignCast(widget))).as(gtk.Editable), @intFromBool(e));
    } else if (std.mem.eql(u8, kind, "TextArea")) {
        if (propStr(props, "text")) |t| {
            const view: *gtk.TextView = @ptrCast(@alignCast(widget));
            const buf = gtk.TextView.getBuffer(view);
            var s_it: gtk.TextIter = undefined;
            var e_it: gtk.TextIter = undefined;
            gtk.TextBuffer.getStartIter(buf, &s_it);
            gtk.TextBuffer.getEndIter(buf, &e_it);
            const cur = gtk.TextBuffer.getText(buf, &s_it, &e_it, 0);
            defer glib.free(@ptrCast(cur));
            if (!std.mem.eql(u8, std.mem.span(cur), t)) {
                blockEcho(asObject(buf));
                gtk.TextBuffer.setText(buf, dupeZ(t), -1);
                unblockEcho(asObject(buf));
            }
        }
    } else if (std.mem.eql(u8, kind, "Checkbox")) {
        if (propBool(props, "checked")) |c| {
            const cb: *gtk.CheckButton = @ptrCast(@alignCast(widget));
            if ((gtk.CheckButton.getActive(cb) != 0) != c) {
                blockEcho(asObject(widget));
                gtk.CheckButton.setActive(cb, @intFromBool(c));
                unblockEcho(asObject(widget));
            }
        }
        if (propStr(props, "label")) |l| gtk.CheckButton.setLabel(@ptrCast(@alignCast(widget)), dupeZ(l));
    } else if (std.mem.eql(u8, kind, "Radio")) {
        if (propBool(props, "checked")) |c| {
            const cb: *gtk.CheckButton = @ptrCast(@alignCast(widget));
            if ((gtk.CheckButton.getActive(cb) != 0) != c) {
                blockEcho(asObject(widget));
                gtk.CheckButton.setActive(cb, @intFromBool(c));
                unblockEcho(asObject(widget));
            }
        }
        if (propStr(props, "label")) |l| gtk.CheckButton.setLabel(@ptrCast(@alignCast(widget)), dupeZ(l));
    } else if (std.mem.eql(u8, kind, "Select")) {
        if (propInt(props, "selectedIndex")) |idx| {
            const dd: *gtk.DropDown = @ptrCast(@alignCast(widget));
            if (gtk.DropDown.getSelected(dd) != @as(c_uint, @intCast(idx))) {
                blockEcho(asObject(widget));
                gtk.DropDown.setSelected(dd, @intCast(idx));
                unblockEcho(asObject(widget));
            }
        }
    } else if (std.mem.eql(u8, kind, "Slider")) {
        if (propFloat(props, "value")) |v| {
            const range = @as(*gtk.Scale, @ptrCast(@alignCast(widget))).as(gtk.Range);
            if (@abs(gtk.Range.getValue(range) - v) > 1e-9) {
                blockEcho(asObject(widget));
                gtk.Range.setValue(range, v);
                unblockEcho(asObject(widget));
            }
        }
    } else if (std.mem.eql(u8, kind, "ProgressBar")) {
        if (propFloat(props, "fraction")) |f| gtk.ProgressBar.setFraction(@ptrCast(@alignCast(widget)), f);
    } else if (std.mem.eql(u8, kind, "Image")) {
        if (propStr(props, "path")) |p_| gtk.Image.setFromFile(@ptrCast(@alignCast(widget)), dupeZ(p_));
        if (propStr(props, "iconName")) |n| gtk.Image.setFromIconName(@ptrCast(@alignCast(widget)), ndicons.symbolic(dupeZ(n)));
    } else if (std.mem.eql(u8, kind, "Spinner")) {
        if (propBool(props, "spinning")) |sp| gtk.Spinner.setSpinning(@ptrCast(@alignCast(widget)), @intFromBool(sp));
    } else if (std.mem.eql(u8, kind, "TabView")) {
        if (propInt(props, "selectedIndex")) |idx| gtk.Notebook.setCurrentPage(@ptrCast(@alignCast(widget)), @intCast(idx));
    } else if (std.mem.eql(u8, kind, "ListView")) {
        {
            const sw: *gtk.ScrolledWindow = @ptrCast(@alignCast(widget));
            const list: *gtk.ListView = @ptrCast(@alignCast(gtk.ScrolledWindow.getChild(sw).?));
            const selection: *gtk.SingleSelection = @ptrCast(@alignCast(gtk.ListView.getModel(list).?));
            const model: *gtk.StringList = @ptrCast(@alignCast(gtk.SingleSelection.getModel(selection).?));
            const n_old = gio.ListModel.getNItems(model.as(gio.ListModel));
            const strv = buildStrv(propArray(props, "items"), dupeZ); // O(n) bulk build, not per-item append
            defer std.heap.page_allocator.free(strv);
            gtk.StringList.splice(model, 0, n_old, @ptrCast(strv.ptr)); // one call: replace-all
        }
        if (propInt(props, "selectedIndex")) |idx| {
            const sw: *gtk.ScrolledWindow = @ptrCast(@alignCast(widget));
            const list: *gtk.ListView = @ptrCast(@alignCast(gtk.ScrolledWindow.getChild(sw).?));
            const selection: *gtk.SingleSelection = @ptrCast(@alignCast(gtk.ListView.getModel(list).?));
            if (idx >= 0) gtk.SingleSelection.setSelected(selection, @intCast(idx));
        }
    } else if (std.mem.eql(u8, kind, "WebView")) {
        if (propStr(props, "url")) |u| ndweb_gtk.setUrl(widget, dupeZ(u));
    } else if (std.mem.eql(u8, kind, "NativeView")) {
        if (propStr(props, "props")) |pj| {
            if (gobject.Object.getData(asObject(widget), "nd-view-kind")) |raw| {
                nd_plugin.viewApplyProps(std.mem.span(@as([*:0]const u8, @ptrCast(raw))), widget, pj);
            }
        }
    } else if (std.mem.eql(u8, kind, "SplitView")) {
        if (propBool(props, "collapsed")) |c| adw.OverlaySplitView.setCollapsed(@ptrCast(@alignCast(widget)), @intFromBool(c));
    } else if (std.mem.eql(u8, kind, "HeaderBar")) {
        ndHeaderBarApplyNav(@ptrCast(@alignCast(widget)), propBool(props, "canGoBack"), null);
        ndHeaderBarApplyNav(@ptrCast(@alignCast(widget)), null, propBool(props, "canGoForward"));
    } else if (std.mem.eql(u8, kind, "SearchInput")) {
        if (propStr(props, "text")) |t| {
            const editable = @as(*gtk.SearchEntry, @ptrCast(@alignCast(widget))).as(gtk.Editable);
            const cur = std.mem.span(gtk.Editable.getText(editable));
            if (!std.mem.eql(u8, cur, t)) {
                blockEcho(asObject(widget));
                gtk.Editable.setText(editable, dupeZ(t));
                unblockEcho(asObject(widget));
            }
        }
        if (propStr(props, "placeholder")) |p_| gtk.SearchEntry.setPlaceholderText(@ptrCast(@alignCast(widget)), dupeZ(p_));
    } else if (std.mem.eql(u8, kind, "SourceList")) {
        {
            const box: *gtk.ListBox = @ptrCast(@alignCast(scrolledWindowInner(@ptrCast(@alignCast(widget))).?));
            const prev = gtk.ListBox.getSelectedRow(box);
            const prev_idx: c_int = if (prev) |r| gtk.ListBoxRow.getIndex(r) else -1;
            blockEcho(asObject(box));
            gtk.ListBox.removeAll(box);
            ndBuildSourceRows(box, propArray(props, "items"), dupeZ);
            if (prev_idx >= 0) {
                if (gtk.ListBox.getRowAtIndex(box, prev_idx)) |r| gtk.ListBox.selectRow(box, r);
            }
            unblockEcho(asObject(box));
        }
        if (propInt(props, "selectedIndex")) |idx| {
            const box: *gtk.ListBox = @ptrCast(@alignCast(scrolledWindowInner(@ptrCast(@alignCast(widget))).?));
            const cur = gtk.ListBox.getSelectedRow(box);
            const cur_idx: i64 = if (cur) |r| gtk.ListBoxRow.getIndex(r) else -1;
            if (cur_idx != idx) {
                blockEcho(asObject(box));
                if (idx >= 0) {
                    if (gtk.ListBox.getRowAtIndex(box, @intCast(idx))) |r| gtk.ListBox.selectRow(box, r);
                } else gtk.ListBox.unselectAll(box);
                unblockEcho(asObject(box));
            }
        }
    } else if (std.mem.eql(u8, kind, "MenuItem")) {
        if (propBool(props, "enabled")) |en| ndMenuItemSetEnabled(widget, en);
    } else if (std.mem.eql(u8, kind, "SettingsGroup")) {
        if (propInt(props, "spacing")) |s| {
            const box: *gtk.Box = @ptrCast(@alignCast(widget));
            gtk.Box.setSpacing(box, @intCast(s));
        }
    } else if (std.mem.eql(u8, kind, "Switch")) {
        if (propBool(props, "checked")) |c| {
            const sw: *gtk.Switch = @ptrCast(@alignCast(widget));
            if ((gtk.Switch.getActive(sw) != 0) != c) {
                blockEcho(asObject(widget));
                gtk.Switch.setActive(sw, @intFromBool(c));
                unblockEcho(asObject(widget));
            }
        }
    } else if (std.mem.eql(u8, kind, "ToggleButton")) {
        if (propStr(props, "label")) |l| {
            const btn = @as(*gtk.ToggleButton, @ptrCast(@alignCast(widget))).as(gtk.Button);
            if (gtk.Button.getChild(btn)) |child| {
                if (gobject.ext.isA(child, adw.ButtonContent)) {
                    // icon+label button: setLabel would replace the whole child
                    adw.ButtonContent.setLabel(@ptrCast(@alignCast(child)), dupeZ(l));
                } else gtk.Button.setLabel(btn, dupeZ(l));
            } else gtk.Button.setLabel(btn, dupeZ(l));
        }
        if (propBool(props, "active")) |a| {
            const tb: *gtk.ToggleButton = @ptrCast(@alignCast(widget));
            if ((gtk.ToggleButton.getActive(tb) != 0) != a) {
                blockEcho(asObject(widget));
                gtk.ToggleButton.setActive(tb, @intFromBool(a));
                unblockEcho(asObject(widget));
            }
        }
    } else if (std.mem.eql(u8, kind, "SegmentedControl")) {
        if (propInt(props, "selectedIndex")) |idx| {
            const group: *adw.ToggleGroup = @ptrCast(@alignCast(widget));
            if (idx >= 0 and adw.ToggleGroup.getActive(group) != @as(c_uint, @intCast(idx))) {
                blockEcho(asObject(widget));
                adw.ToggleGroup.setActive(group, @intCast(idx));
                unblockEcho(asObject(widget));
            }
        }
    } else if (std.mem.eql(u8, kind, "NumberInput")) {
        if (propFloat(props, "value")) |v| {
            const spin: *gtk.SpinButton = @ptrCast(@alignCast(widget));
            if (@abs(gtk.SpinButton.getValue(spin) - v) > 1e-9) {
                blockEcho(asObject(widget));
                gtk.SpinButton.setValue(spin, v);
                unblockEcho(asObject(widget));
            }
        }
    } else if (std.mem.eql(u8, kind, "LinkButton")) {
        if (propStr(props, "label")) |l| gtk.Button.setLabel(@as(*gtk.LinkButton, @ptrCast(@alignCast(widget))).as(gtk.Button), dupeZ(l));
        if (propStr(props, "uri")) |u| gtk.LinkButton.setUri(@ptrCast(@alignCast(widget)), dupeZ(u));
        if (propBool(props, "visited")) |v| gtk.LinkButton.setVisited(@ptrCast(@alignCast(widget)), @intFromBool(v));
        if (propBool(props, "openExternal")) |oe| gobject.Object.setData(asObject(widget), "nd-open-external", if (oe) @as(?*anyopaque, @ptrFromInt(1)) else null);
    } else if (std.mem.eql(u8, kind, "LevelIndicator")) {
        if (propFloat(props, "value")) |v| gtk.LevelBar.setValue(@ptrCast(@alignCast(widget)), v);
        // warning/critical merge in one call (absent keys keep prior state).
        ndLevelBarApplyOffsets(@ptrCast(@alignCast(widget)), propFloat(props, "warningValue"), propFloat(props, "criticalValue"));
        // handled together with warningValue above (ndLevelBarApplyOffsets merges both).
    } else if (std.mem.eql(u8, kind, "ColorPicker")) {
        if (propStr(props, "value")) |v| {
            const btn: *gtk.ColorDialogButton = @ptrCast(@alignCast(widget));
            var rgba: gdk.RGBA = undefined;
            if (gdk.RGBA.parse(&rgba, dupeZ(v)) != 0) {
                if (!ndRgbaClose(gtk.ColorDialogButton.getRgba(btn), &rgba)) {
                    blockEcho(asObject(widget));
                    gtk.ColorDialogButton.setRgba(btn, &rgba);
                    unblockEcho(asObject(widget));
                }
            }
        }
    } else if (std.mem.eql(u8, kind, "Banner")) {
        if (propStr(props, "title")) |t| adw.Banner.setTitle(@ptrCast(@alignCast(widget)), dupeZ(t));
        if (propStr(props, "buttonLabel")) |bl| adw.Banner.setButtonLabel(@ptrCast(@alignCast(widget)), if (bl.len > 0) dupeZ(bl).ptr else null);
        if (propBool(props, "revealed")) |r| adw.Banner.setRevealed(@ptrCast(@alignCast(widget)), @intFromBool(r));
    } else if (std.mem.eql(u8, kind, "MenuButton")) {
        if (propStr(props, "label")) |l| gtk.MenuButton.setLabel(@ptrCast(@alignCast(widget)), dupeZ(l));
        if (propStr(props, "iconName")) |ic| gtk.MenuButton.setIconName(@ptrCast(@alignCast(widget)), ndicons.symbolic(dupeZ(ic)));
    } else if (std.mem.eql(u8, kind, "SplitButton")) {
        if (propStr(props, "label")) |l| adw.SplitButton.setLabel(@ptrCast(@alignCast(widget)), dupeZ(l));
        if (propStr(props, "iconName")) |ic| adw.SplitButton.setIconName(@ptrCast(@alignCast(widget)), ndicons.symbolic(dupeZ(ic)));
    } else if (std.mem.eql(u8, kind, "Popover")) {
        if (propBool(props, "open")) |o| {
            const pop: *gtk.Popover = @ptrCast(@alignCast(widget));
            const up = gtk.Widget.getVisible(widget) != 0;
            if (o and !up) {
                if (gtk.Widget.getParent(widget) != null) gtk.Popover.popup(pop)
                else gobject.Object.setData(asObject(pop), ND_POPOVER_PENDING_OPEN, @ptrFromInt(1)); // not anchored yet: open on attach
            } else if (!o and up) {
                blockEcho(asObject(widget)); // programmatic popdown: `closed` must not echo
                gtk.Popover.popdown(pop);
                unblockEcho(asObject(widget));
            }
        }
        if (propStr(props, "position")) |pos| gtk.Popover.setPosition(@ptrCast(@alignCast(widget)), ndPositionFromString(pos));
    } else if (std.mem.eql(u8, kind, "Expander")) {
        if (propStr(props, "label")) |l| gtk.Expander.setLabel(@ptrCast(@alignCast(widget)), dupeZ(l));
        if (propBool(props, "expanded")) |e| {
            const ex: *gtk.Expander = @ptrCast(@alignCast(widget));
            if ((gtk.Expander.getExpanded(ex) != 0) != e) {
                blockEcho(asObject(widget));
                gtk.Expander.setExpanded(ex, @intFromBool(e));
                unblockEcho(asObject(widget));
            }
        }
    } else if (std.mem.eql(u8, kind, "StatusPage")) {
        if (propStr(props, "iconName")) |ic| adw.StatusPage.setIconName(@ptrCast(@alignCast(widget)), ndicons.symbolic(dupeZ(ic)));
        if (propStr(props, "title")) |t| adw.StatusPage.setTitle(@ptrCast(@alignCast(widget)), dupeZ(t));
        if (propStr(props, "description")) |d| adw.StatusPage.setDescription(@ptrCast(@alignCast(widget)), dupeZ(d));
    } else if (std.mem.eql(u8, kind, "DatePicker")) {
        if (propStr(props, "value")) |v| {
            if (ndDateKeyFromIso(v)) |key| {
                const cal: *gtk.Calendar = @ptrCast(@alignCast(widget));
                if (ndCalendarDateKey(cal) != key) {
                    blockEcho(asObject(widget));
                    ndCalendarSelectKey(cal, key);
                    unblockEcho(asObject(widget));
                }
            }
        }
        // min/max merge in one call (absent keys keep prior state).
        ndCalendarSetLimits(@ptrCast(@alignCast(widget)), propStr(props, "minDate"), propStr(props, "maxDate"));
        // handled together with minDate above (ndCalendarSetLimits merges both).
    } else if (std.mem.eql(u8, kind, "Table")) {
        ndtable_gtk.applyProps(widget, props, dupeZ);
    } else if (std.mem.eql(u8, kind, "TreeView")) {
        ndtree_gtk.applyProps(widget, props, dupeZ);
    } else if (std.mem.eql(u8, kind, "FontPicker")) {
        if (propStr(props, "value")) |v| {
            const btn: *gtk.FontDialogButton = @ptrCast(@alignCast(widget));
            const new_desc = pango.FontDescription.fromString(dupeZ(v));
            const same = if (gtk.FontDialogButton.getFontDesc(btn)) |cur| pango.FontDescription.equal(cur, new_desc) != 0 else false;
            if (!same) {
                blockEcho(asObject(widget));
                gtk.FontDialogButton.setFontDesc(btn, new_desc);
                unblockEcho(asObject(widget));
            }
            pango.FontDescription.free(new_desc); // setFontDesc copies
        }
    } else if (std.mem.eql(u8, kind, "Video")) {
        if (propStr(props, "src")) |s| {
            if (gobject.ext.isA(widget, gtk.Video)) ndVideoSetSrc(@ptrCast(@alignCast(widget)), dupeZ(s)); // placeholder label when no media module
        }
        if (propBool(props, "loop")) |l| {
            if (gobject.ext.isA(widget, gtk.Video)) gtk.Video.setLoop(@ptrCast(@alignCast(widget)), @intFromBool(l));
        }
    } else if (std.mem.eql(u8, kind, "TrayItem")) {
        // ND_PLATFORM_NOOP(TrayItem): prop "iconName" is a no-op on this platform by design.
        // ND_PLATFORM_NOOP(TrayItem): prop "tooltip" is a no-op on this platform by design.
    } else if (std.mem.eql(u8, kind, "ShareButton")) {
        // ND_PLATFORM_NOOP(ShareButton): prop "label" is a no-op on this platform by design.
        // ND_PLATFORM_NOOP(ShareButton): prop "items" is a no-op on this platform by design.
    } else if (std.mem.eql(u8, kind, "Paned")) {
        if (propFloat(props, "position")) |frac| {
            ndPanedApplyPosition(@ptrCast(@alignCast(widget)), frac);
        }
    }
}

fn lvSetup(_: *gobject.Object, list_item: *gtk.ListItem, _: ?*anyopaque) callconv(.c) void {
    const label = gtk.Label.new(null);
    gtk.ListItem.setChild(list_item, label.as(gtk.Widget));
}
fn lvBind(_: *gobject.Object, list_item: *gtk.ListItem, _: ?*anyopaque) callconv(.c) void {
    const child = gtk.ListItem.getChild(list_item) orelse return;
    const label: *gtk.Label = @ptrCast(@alignCast(child));
    const obj = gtk.ListItem.getItem(list_item) orelse return;
    const so: *gtk.StringObject = @ptrCast(@alignCast(obj));
    gtk.Label.setText(label, gtk.StringObject.getString(so));
}

fn cbHoverEnter(_: *gtk.EventControllerMotion, _: f64, _: f64, data: ?*anyopaque) callconv(.c) void {
    const node_id: u32 = @intCast(@intFromPtr(data));
    if (emit) |f| f(node_id, "hoverChanged", .{ .checked = true });
}
fn cbHoverLeave(_: *gtk.EventControllerMotion, data: ?*anyopaque) callconv(.c) void {
    const node_id: u32 = @intCast(@intFromPtr(data));
    if (emit) |f| f(node_id, "hoverChanged", .{ .checked = false });
}
fn ndHoverConnect(widget: *gtk.Widget, data: ?*anyopaque) void {
    const ctrl = gtk.EventControllerMotion.new();
    _ = gtk.EventControllerMotion.signals.enter.connect(ctrl, ?*anyopaque, &cbHoverEnter, data, .{});
    _ = gtk.EventControllerMotion.signals.leave.connect(ctrl, ?*anyopaque, &cbHoverLeave, data, .{});
    gtk.Widget.addController(widget, ctrl.as(gtk.EventController));
}

